"""Warehouse fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.catalog_service import CatalogService
from orders.application.customer_service import CustomerService
from orders.application.errors import Conflict, CustomerNotFound, OrderNotFound, ProductNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_non_negative_int, require_positive_int, require_str)


class FulfilmentController:
    def __init__(self, orders: OrderService, customers: CustomerService, catalog: CatalogService) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            order = self._orders.get_order(order_id)
        except OrderNotFound:
            return not_found("order")
        if order.status == "cancelled":
            return conflict(Conflict(f"order {order_id} is cancelled"))
        try:
            customer = self._customers.get(order.customer_id)
            lines: list[dict[str, Any]] = []
            for item in order.items:
                product = self._catalog.get_product(item.sku)
                lines.append({"sku": item.sku, "name": product.name, "quantity": item.quantity})
        except (CustomerNotFound, ProductNotFound) as exc:
            # Both are guaranteed by place_order; reaching here means the data is inconsistent.
            raise RuntimeError(f"order {order_id} references missing data: {exc}") from exc
        return Response(200, {"order_id": order.order_id, "customer_name": customer.name, "lines": lines})

    def handle_low_stock(self, threshold: Any) -> Response:
        """Active products whose stock on hand is strictly below ``threshold``, lowest stock first."""
        try:
            limit = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        rows = []
        for product in self._catalog.list_active():
            on_hand = self._catalog.on_hand(product.sku)
            if on_hand < limit:
                rows.append({"sku": product.sku, "name": product.name, "on_hand": on_hand})
        rows.sort(key=lambda row: (row["on_hand"], row["sku"]))
        return Response(200, {"products": rows})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        """Add units to a product's stock. Validation runs before any change is made."""
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            on_hand = self._catalog.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, {"sku": sku, "on_hand": on_hand})

